solution.code:
const URUTAN = { tinggi: 0, sedang: 1, rendah: 2 };

class DaftarTugas {
  #berikutnyaId = 1;

  constructor(tugas = []) {
    this.tugas = tugas.map((t) => ({ ...t }));
    this.#berikutnyaId = Math.max(0, ...this.tugas.map((t) => t.id)) + 1;
  }

  tambah(judul, { prioritas = "sedang", tenggat } = {}) {
    const bersih = String(judul ?? "").trim();
    if (!bersih) throw new Error("Judul wajib diisi");
    if (!Object.hasOwn(URUTAN, prioritas)) throw new Error("Prioritas tidak dikenal");
    const tugas = { id: this.#berikutnyaId++, judul: bersih, prioritas, selesai: false };
    if (tenggat) tugas.tenggat = tenggat;
    this.tugas.push(tugas);
    return tugas;
  }

  selesaikan(id) {
    const tugas = this.tugas.find((t) => t.id === id);
    if (!tugas) return false;
    tugas.selesai = true;
    return true;
  }

  hapus(id) {
    const sebelum = this.tugas.length;
    this.tugas = this.tugas.filter((t) => t.id !== id);
    return this.tugas.length < sebelum;
  }

  filter({ selesai, prioritas } = {}) {
    return this.tugas.filter(
      (t) => (selesai === undefined || t.selesai === selesai) && (prioritas === undefined || t.prioritas === prioritas)
    );
  }

  urutkan() {
    return [...this.tugas].sort((a, b) => URUTAN[a.prioritas] - URUTAN[b.prioritas] || a.id - b.id);
  }

  ringkasan() {
    const selesai = this.tugas.filter((t) => t.selesai).length;
    return { total: this.tugas.length, selesai, sisa: this.tugas.length - selesai };
  }

  toJSON() {
    return this.tugas.map((t) => ({ ...t }));
  }

  static dariJSON(teks) {
    let data;
    try {
      data = JSON.parse(teks);
    } catch {
      throw new Error("JSON tidak valid");
    }
    if (!Array.isArray(data)) throw new Error("JSON tidak valid");
    return new DaftarTugas(data);
  }

  async simpan(storage) {
    await storage.setItem("tugas", JSON.stringify(this));
    return this.tugas.length;
  }
}

