solution.code:
function namaLulus(siswa) {
  return siswa.filter(s => s.nilai >= 75).map(s => s.nama);
}

function rataRata(siswa) {
  if (siswa.length === 0) return 0;
  const total = siswa.reduce((t, s) => t + s.nilai, 0);
  return total / siswa.length;
}

function cariSiswa(siswa, nama) {
  return siswa.find(s => s.nama === nama);
}

function hitungPerKota(siswa) {
  const hasil = {};
  for (const s of siswa) {
    hasil[s.kota] = (hasil[s.kota] || 0) + 1;
  }
  return hasil;
}

