solution.code:
async function ambilAman(daftar) {
  const hasil = await Promise.allSettled(daftar);
  return hasil.map((h) => (h.status === "fulfilled" ? h.value : null));
}

function* rentang(awal, akhir, langkah = 1) {
  for (let i = awal; i <= akhir; i += langkah) {
    yield i;
  }
}

function hitungKata(teks) {
  const hasil = new Map();
  for (const kata of teks.split(" ")) {
    hasil.set(kata, (hasil.get(kata) ?? 0) + 1);
  }
  return hasil;
}

