solution.code:
async function muatProfil(ambil) {
  try {
    const user = await ambil();
    return {
      nama: user?.profil?.nama ?? "Tamu",
      kota: user?.alamat?.kota ?? "-",
    };
  } catch (err) {
    return { error: err.message };
  }
}

function kodeInvoice(n) {
  return "INV-" + String(n).padStart(4, "0");
}

class Dompet {
  #saldo = 0;

  setor(jumlah) {
    this.#saldo += jumlah;
  }

  get saldo() {
    return this.#saldo;
  }
}
